import { createContext, useContext, useReducer, type ReactNode } from 'react';

interface AuthUser {
  userId: string;
  tenantId: string;
  displayName: string;
  securityGroups: string[];
}

type AuthState =
  | { status: 'loading' }
  | { status: 'authenticated'; user: AuthUser; token: string }
  | { status: 'unauthenticated' };

type AuthAction =
  | { type: 'LOGIN_SUCCESS'; user: AuthUser; token: string }
  | { type: 'LOGOUT' }
  | { type: 'TOKEN_REFRESH'; token: string };

function authReducer(state: AuthState, action: AuthAction): AuthState {
  switch (action.type) {
    case 'LOGIN_SUCCESS': return { status: 'authenticated', user: action.user, token: action.token };
    case 'LOGOUT': return { status: 'unauthenticated' };
    case 'TOKEN_REFRESH':
      return state.status === 'authenticated' ? { ...state, token: action.token } : state;
    default: return state;
  }
}

const AuthContext = createContext<{ state: AuthState; dispatch: React.Dispatch<AuthAction> } | null>(null);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [state, dispatch] = useReducer(authReducer, { status: 'loading' });
  return <AuthContext.Provider value={{ state, dispatch }}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error('useAuth must be used within AuthProvider');
  return ctx;
}

import { createSlice, createAsyncThunk, type PayloadAction } from '@reduxjs/toolkit';

interface Message { id: string; role: string; content: string; createdAt: string; }
interface Conversation { id: string; title: string; messages: Message[]; }

interface ConversationsState {
  conversations: Conversation[];
  activeId: string | null;
  status: 'idle' | 'loading' | 'error';
  error: string | null;
}

export const fetchConversations = createAsyncThunk(
  'conversations/fetchAll',
  async (tenantId: string, { rejectWithValue }) => {
    const res = await fetch(`/api/conversations?tenantId=${tenantId}`);
    if (!res.ok) return rejectWithValue(await res.text());
    return (await res.json()) as Conversation[];
  }
);

const conversationsSlice = createSlice({
  name: 'conversations',
  initialState: { conversations: [], activeId: null, status: 'idle', error: null } as ConversationsState,
  reducers: {
    setActive: (state, action: PayloadAction<string>) => {
      state.activeId = action.payload;
    },
    appendMessage: (state, action: PayloadAction<{ conversationId: string; message: Message }>) => {
      const conv = state.conversations.find((c) => c.id === action.payload.conversationId);
      conv?.messages.push(action.payload.message);
    },
  },
  extraReducers: (builder) => {
    builder
      .addCase(fetchConversations.pending, (state) => { state.status = 'loading'; state.error = null; })
      .addCase(fetchConversations.fulfilled, (state, action) => {
        state.status = 'idle';
        state.conversations = action.payload;
      })
      .addCase(fetchConversations.rejected, (state, action) => {
        state.status = 'error';
        state.error = action.payload as string;
      });
  },
});

export const { setActive, appendMessage } = conversationsSlice.actions;
export default conversationsSlice.reducer;

import { createSelector } from '@reduxjs/toolkit';
import type { RootState } from '../store';

const selectConversations = (state: RootState) => state.conversations.conversations;
const selectActiveId = (state: RootState) => state.conversations.activeId;

// Memoized: only recomputes when input selectors produce new references
export const selectActiveMessages = createSelector(
  [selectConversations, selectActiveId],
  (conversations, activeId) =>
    conversations.find((c) => c.id === activeId)?.messages ?? []
);
